import React, { useState } from 'react';
import Blobs from '../components/Blobs';
import { useMoods } from '../hooks/useStorage';

const MOODS = [
  { score:1, emoji:'😔', label:'Väldigt dåligt' },
  { score:2, emoji:'😟', label:'Dåligt' },
  { score:3, emoji:'😐', label:'Okej' },
  { score:4, emoji:'🙂', label:'Bra' },
  { score:5, emoji:'😄', label:'Väldigt bra' },
];

export default function CheckIn({ setPage }) {
  const { addMood, todayChecked } = useMoods();
  const [selected, setSelected] = useState(null);
  const [note, setNote]         = useState('');
  const [saved, setSaved]       = useState(false);

  const handleSave = () => {
    if (!selected) return;
    const m = MOODS.find(m => m.score === selected);
    addMood(m.score, m.emoji, m.label, note);
    setSaved(true);
  };

  if (saved || todayChecked) {
    return (
      <div style={{ minHeight:'100vh', position:'relative', display:'flex', alignItems:'center', justifyContent:'center' }}>
        <Blobs variant="blue" />
        <div style={{ position:'relative', zIndex:1, textAlign:'center', padding:'0 24px', animation:'fadeUp .7s cubic-bezier(0.16,1,0.3,1) both' }}>
          <div style={{ fontSize:64, marginBottom:24 }}>{saved ? '✅' : '🌿'}</div>
          <h2 style={{ fontSize:'clamp(28px,6vw,44px)', fontWeight:700, letterSpacing:'-0.04em', color:'#fff', marginBottom:16 }}>
            {saved ? 'Incheckning sparad' : 'Redan incheckad'}
          </h2>
          <p style={{ fontSize:15, color:'rgba(255,255,255,0.4)', marginBottom:40, fontWeight:300, maxWidth:280, margin:'0 auto 40px' }}>
            {saved ? 'Bra att du tog en stund för dig själv idag.' : 'Du har redan gjort din incheckning. Kom tillbaka imorgon!'}
          </p>
          <div style={{ display:'flex', gap:12, justifyContent:'center', flexWrap:'wrap' }}>
            <button onClick={() => setPage('history')} style={{ padding:'12px 24px', borderRadius:100, background:'#fff', color:'#0e0e12', fontSize:13, fontWeight:600 }}>Se historik</button>
            <button onClick={() => setPage('home')} style={{ padding:'12px 24px', borderRadius:100, background:'rgba(255,255,255,0.08)', border:'1px solid rgba(255,255,255,0.12)', color:'rgba(255,255,255,0.7)', fontSize:13 }}>Tillbaka</button>
          </div>
        </div>
      </div>
    );
  }

  return (
    <div style={{ minHeight:'100vh', position:'relative', display:'flex', alignItems:'center', justifyContent:'center' }}>
      <Blobs variant="blue" />
      <div style={{ position:'relative', zIndex:1, padding:'80px 24px 48px', width:'100%', maxWidth:480, animation:'fadeUp .7s cubic-bezier(0.16,1,0.3,1) both' }}>

        <p style={{ fontFamily:'DM Mono,monospace', fontSize:10, letterSpacing:'0.2em', textTransform:'uppercase', color:'rgba(255,255,255,0.3)', marginBottom:16, textAlign:'center' }}>
          Daglig check-in
        </p>
        <h1 style={{ fontSize:'clamp(32px,7vw,52px)', fontWeight:700, letterSpacing:'-0.04em', color:'#fff', textAlign:'center', marginBottom:12, lineHeight:1 }}>
          Hur mår du idag?
        </h1>
        <p style={{ fontSize:13, color:'rgba(255,255,255,0.35)', textAlign:'center', marginBottom:52, fontWeight:300 }}>
          En snabb incheckning — tar bara 10 sekunder.
        </p>

        {/* Mood buttons */}
        <div style={{ display:'flex', gap:10, justifyContent:'center', marginBottom:36, flexWrap:'wrap' }}>
          {MOODS.map(m => (
            <button key={m.score} onClick={() => setSelected(m.score)}
              style={{
                display:'flex', flexDirection:'column', alignItems:'center', gap:8,
                padding:'20px 16px', minWidth:80,
                background: selected === m.score ? 'rgba(255,255,255,0.1)' : 'rgba(255,255,255,0.04)',
                border: `1px solid ${selected === m.score ? 'rgba(255,255,255,0.25)' : 'rgba(255,255,255,0.07)'}`,
                borderRadius:16,
                transform: selected === m.score ? 'translateY(-4px)' : 'none',
                transition:'all .25s cubic-bezier(0.16,1,0.3,1)',
                backdropFilter:'blur(20px)',
              }}>
              <span style={{ fontSize:32 }}>{m.emoji}</span>
              <span style={{ fontSize:10, color:'rgba(255,255,255,0.4)', textAlign:'center', lineHeight:1.3, fontFamily:'DM Mono,monospace', letterSpacing:'0.06em' }}>{m.label}</span>
            </button>
          ))}
        </div>

        {/* Note */}
        <textarea value={note} onChange={e => setNote(e.target.value)} maxLength={255}
          placeholder="Valfritt: kort notering om dagen..."
          style={{ width:'100%', background:'rgba(255,255,255,0.04)', border:'1px solid rgba(255,255,255,0.07)', borderRadius:14, padding:'16px', color:'#fff', fontSize:14, fontWeight:300, resize:'none', height:80, outline:'none', marginBottom:20, transition:'border-color .2s' }}
          onFocus={e=>e.target.style.borderColor='rgba(255,255,255,0.18)'}
          onBlur={e=>e.target.style.borderColor='rgba(255,255,255,0.07)'}
        />

        <button onClick={handleSave} disabled={!selected}
          style={{ width:'100%', padding:'15px', borderRadius:100, background: selected ? '#fff' : 'rgba(255,255,255,0.1)', color: selected ? '#0e0e12' : 'rgba(255,255,255,0.25)', fontSize:14, fontWeight:600, transition:'all .25s' }}>
          Spara incheckning
        </button>
      </div>
    </div>
  );
}
